<script setup lang="ts">
import { ref } from 'vue'; import { useToast } from 'primevue/usetoast'; import Dialog from 'primevue/dialog'; import Button from 'primevue/button'; import Textarea from 'primevue/textarea';
import AppShell from '../layouts/AppShell.vue'; import RequestTable from '../components/RequestTable.vue'; import RequestDetail from '../components/RequestDetail.vue';
import { requests, trace } from '../services/mock'; import type { RepairRequest } from '../types';
const toast=useToast(), items=ref(requests.filter(r=>r.assigned_department==='HYD'&&r.status==='ASSIGNED')), selected=ref<RepairRequest|null>(items.value[0]||null), rejectOpen=ref(false), reason=ref('');
function accept(){ if(!selected.value)return;selected.value.status='ACCEPTED';items.value=[...items.value];toast.add({severity:'success',summary:'배정 수락',detail:'정비 업무가 접수되었습니다.',life:2500}); }
function reject(){ if(!selected.value||!reason.value.trim())return;selected.value.status='HUMAN_REVIEW';selected.value.review_reason='TEAM_REJECTED';items.value=items.value.filter(r=>r.id!==selected.value?.id);rejectOpen.value=false;toast.add({severity:'warn',summary:'사람 검토 인계',detail:'거절 사유가 어드민 검토 큐에 전달되었습니다.',life:3000});selected.value=items.value[0]||null; }
</script>
<template><AppShell><template #role>정비팀 · HYD</template><div class="page-title"><div><span>MAINTENANCE WORKSPACE</span><h1>정비 배정 큐</h1><p>유압·착륙장치팀에 배정된 요청과 Agent 근거를 검토합니다.</p></div><div class="live-pill"><i class="pi pi-circle-fill"/> LIVE QUEUE</div></div><div class="metric-strip"><div><small>신규 배정</small><b>{{ items.length }}</b></div><div><small>AOG</small><b class="danger-text">0</b></div><div><small>평균 응답</small><b>6m</b></div><div><small>오늘 수락</small><b>4</b></div></div><div class="console-grid"><div class="queue-panel"><div class="panel-head"><div><b>부서 대기함</b><small>ASSIGNED · HYD</small></div><Button label="새로고침" icon="pi pi-refresh" text/></div><RequestTable :items="items" :selected="selected" @select="selected=$event"/></div><RequestDetail :request="selected" :trace="trace" mode="maintenance" @accept="accept" @reject="rejectOpen=true"/></div><Dialog v-model:visible="rejectOpen" modal header="배정 거절" :style="{width:'480px'}"><p class="dialog-copy">거절 시 요청은 자동 재배정되지 않고 어드민 사람 검토 큐로 이동합니다.</p><Textarea v-model="reason" rows="4" fluid placeholder="담당 부서 불일치, 정보 부족 등 사유를 입력하세요."/><template #footer><Button label="취소" text @click="rejectOpen=false"/><Button label="거절 및 인계" severity="danger" :disabled="!reason.trim()" @click="reject"/></template></Dialog></AppShell></template>
